INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", 1, 2, -416.5, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", "ヤマト", "2024/10/31 12:00:00", 3001100, 2.1, 130011, 0, 3001, 100);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", 4, 2, -416.5, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", "ヤマト", "2024/10/31 12:00:00", 3001101, 5.68, 130011, 0, 3001, 101);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", 1, 1, -416.5, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", "ヤマト", "2024/10/31 12:00:00", 3001102, 0, 130011, 0, 3001, 102);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", 1, 1, -416.5, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", "フブキ", "2024/10/31 12:00:00", 3002100, 0, 130211, 0, 3002, 100);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", 1, 1, -416.5, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", "フブキ", "2024/10/31 12:00:00", 3002101, 0, 130211, 0, 3002, 101);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", 5, 2, -416.5, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", "フブキ", "2024/10/31 12:00:00", 3002102, 8.53, 130211, 0, 3002, 102);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", 7, 1, -416.5, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", "フブキ", "2024/10/31 12:00:00", 3002103, 5.67, 130211, 0, 3002, 103);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", 1, 1, -416.5, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", "フブキ", "2024/10/31 12:00:00", 3002104, 0, 130211, 0, 3002, 104);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", 3, 3, -416.5, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", "フブキ", "2024/10/31 12:00:00", 3002300, 0, 130211, 0, 3004, 300);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", 7, 7, -416.5, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", "フブキ", "2024/10/31 12:00:00", 3002400, 0, 130211, 0, 3005, 301);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", 2, 1, -416.5, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", "フブキ", "2024/10/31 12:00:00", 3003200, 4.4, 130211, 0, 3003, 200);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", 7, 7, -416.5, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", "フブキ", "2024/10/31 12:00:00", 3003201, 0, 130211, 0, 3003, 201);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES ("2030/01/01 14:59:59", 1, 2, -416.5, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", "フブキ", "2024/10/31 12:00:00", 3003202, 5.6, 130211, 0, 3003, 202);
